const row = $input.first()?.json || {};
const parsedData = $('Parse search command').first().json;
const rawName = (parsedData.search_text || '').trim();
const seconds = Number(row.seconds_elapsed || 0);

if (!row.current_state) {
  return [{ json: { action: 'none' } }];
}

if (!rawName) {
  return [{ json: { action: 'invalid_name', reason: 'empty' } }];
}

if (seconds > 600) {
  return [{
    json: {
      action: 'expired',
      mode: row.mode || null,
      playlist_id: row.playlist_id || null
    }
  }];
}

if (row.mode === 'rename') {
  return [{
    json: {
      action: 'rename',
      playlist_id: Number(row.playlist_id),
      new_name: rawName
    }
  }];
}

if (row.mode === 'create') {
  return [{
    json: {
      action: 'create',
      new_name: rawName
    }
  }];
}

return [{ json: { action: 'none' } }];

