const searchText = $('Parse search command').first().json.search_text || '';
const cleanQuery = searchText
  .replace(/[^\w\s\u0400-\u04FF-]/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    search_query: encodeURIComponent(cleanQuery)
  }
}];

const files = $input.all().map(item => item.json);
const parsedData = $('Parse search command').first().json;
const chatId = parsedData.chat_id;
const replyToMessageId = parsedData.message_id;
const query = parsedData.search_text || '';

const pageSize = 8;
const offset = Number($json.offset || 0);
const filesPage = files.slice(offset, offset + pageSize);

const inline_keyboard = filesPage.map(file => ([
  {
    text: `${file.title} — ${file.artist}`,
    callback_data: `get|${file.id}`
  }
]));

if (offset + filesPage.length < files.length) {
  inline_keyboard.push([
    {
      text: 'More…',
      callback_data: `more|${query}|${offset + filesPage.length}`
    }
  ]);
}

return [{
  json: {
    chat_id: chatId,
    reply_to_message_id: replyToMessageId,
    text: `🔎 Search results for: "${query}"\n\nSelect a track:\n\n@PocketSound_bot`,
    reply_markup: { inline_keyboard }
  }
}];

